import * as THREE from 'three';
import { Line2 } from 'three/addons/lines/Line2.js';
import { LineGeometry } from 'three/addons/lines/LineGeometry.js';
import { LineMaterial } from 'three/addons/lines/LineMaterial.js';
import { CSS2DObject, CSS2DRenderer } from 'three/addons/renderers/CSS2DRenderer.js';
import { GlobeControls, TilesRenderer } from '3d-tiles-renderer/three';
import {
  ImageOverlayPlugin,
  QuantizedMeshPlugin,
  WMTSTilesOverlay,
} from '3d-tiles-renderer/three/plugins';
import { GEOADMIN, LAYERS, SWISS_BOUNDS, wmtsTemplate } from './constants.js';
import { radians, wgs84ToLv95 } from './geo.js';

const CARTOGRAPHIC = { lat: 0, lon: 0, height: 0 };
const ROUTE_SURFACE_OFFSET_METERS = 10;

class ToggleableWmtsOverlay extends WMTSTilesOverlay {
  constructor(options, enabled = true) {
    super(options);
    this.enabled = enabled;
    this.activeLocks = new Map();
  }

  rangeKey(range, level) {
    return `${range.join('_')}_${level}`;
  }

  hasContent(range, level = this.calculateLevel(range)) {
    return this.enabled && super.hasContent(range, level);
  }

  lockTexture(range, level = this.calculateLevel(range)) {
    if (!this.enabled) return null;
    const key = this.rangeKey(range, level);
    this.activeLocks.set(key, (this.activeLocks.get(key) || 0) + 1);
    return super.lockTexture(range, level);
  }

  releaseTexture(range, level = this.calculateLevel(range)) {
    const key = this.rangeKey(range, level);
    const count = this.activeLocks.get(key) || 0;
    if (!count) return;
    if (count === 1) this.activeLocks.delete(key);
    else this.activeLocks.set(key, count - 1);
    super.releaseTexture(range, level);
  }
}

class DeferredImageOverlayPlugin extends ImageOverlayPlugin {
  activateOverlay(overlay) {
    const overlayState = this.overlayInfo.get(overlay);
    if (!overlayState) return;
    this.processedTiles.forEach((tile) => {
      if (this.pendingTiles.has(tile)) return;
      const info = overlayState.tileInfo.get(tile);
      if (!info?.range || info.target || info.refreshing || !overlay.hasContent(info.range)) return;
      info.refreshing = true;
      overlay.lockTexture(info.range);
      this._fetchTileOverlayTexture(tile, overlay, info)
        .then(() => this._updateLayers(tile))
        .finally(() => {
          info.refreshing = false;
        });
    });
  }
}

export class SwissTerrainMap {
  constructor(container, { onError = () => {} } = {}) {
    this.container = container;
    this.onError = onError;
    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(0x9eb6b0);
    this.camera = new THREE.PerspectiveCamera(42, 1, 10, 20_000_000);
    this.renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    // A 1.35 mobile cap is visibly upscaled by high-density phone displays.
    // Two device pixels per CSS pixel keeps the map crisp without rendering at
    // the full 3x/4x density of some devices.
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    // The WMTS imagery is already colour-correct sRGB map material. Additional
    // filmic tone mapping would turn the Landeskarte's white into grey.
    this.renderer.toneMapping = THREE.NoToneMapping;
    this.renderer.domElement.className = 'map-canvas';
    this.renderer.domElement.setAttribute('aria-label', 'Interaktive 3D-Karte der Schweiz');
    container.append(this.renderer.domElement);
    this.labelRenderer = new CSS2DRenderer();
    this.labelRenderer.domElement.className = 'map-label-layer';
    this.labelRenderer.domElement.setAttribute('aria-hidden', 'true');
    container.append(this.labelRenderer.domElement);

    // Uniform light preserves the source tile colours while the terrain mesh
    // still provides the three-dimensional surface.
    // MeshStandardMaterial applies a Lambert 1/PI factor to ambient irradiance.
    // PI therefore reproduces the unmodified WMTS texture value.
    this.scene.add(new THREE.AmbientLight(0xffffff, Math.PI));

    this.tiles = new TilesRenderer(GEOADMIN.terrain);
    this.tiles.fetchOptions.mode = 'cors';
    const mobile = window.innerWidth < 760;
    this.mobile = mobile;
    this.defaultTerrainErrorTarget = mobile ? 8 : 4;
    // A route fills far more of the narrow mobile viewport than the national
    // overview. Refine it further so the imagery is not taken from a stretched
    // low-zoom terrain parent tile.
    this.routeTerrainErrorTarget = mobile ? 0.25 : 4;
    this.tiles.errorTarget = this.defaultTerrainErrorTarget;
    this.tiles.lruCache.minSize = mobile ? 70 : 140;
    this.tiles.lruCache.maxSize = mobile ? 100 : 220;
    this.tiles.lruCache.minBytesSize = (mobile ? 55 : 115) * 1024 * 1024;
    this.tiles.lruCache.maxBytesSize = (mobile ? 80 : 160) * 1024 * 1024;
    this.tiles.registerPlugin(new QuantizedMeshPlugin({ generateNormals: true }));
    this.imagePlugin = new DeferredImageOverlayPlugin({
      renderer: this.renderer,
      // Refined mobile terrain tiles cover a smaller screen region, so 256 px
      // avoids exhausting the phone cache while desktop keeps 512 px.
      resolution: mobile ? 256 : 512,
      enableTileSplitting: true,
    });
    this.tiles.registerPlugin(this.imagePlugin);
    this.tiles.group.rotation.x = -Math.PI / 2;
    this.scene.add(this.tiles.group);

    this.overlayGroup = new THREE.Group();
    this.scene.add(this.overlayGroup);

    this.tiles.addEventListener('load-error', (event) => {
      this.onError(`Kartendaten konnten teilweise nicht geladen werden: ${event.url || ''}`);
    });
    this.tiles.setCamera(this.camera);
    this.tiles.setResolutionFromRenderer(this.camera, this.renderer);
    this.controls = new GlobeControls(this.scene, this.camera, this.renderer.domElement, this.tiles);
    this.controls.enableDamping = true;
    this.controls.dampingFactor = 0.12;
    this.controls.minDistance = 300;
    // geo.admin.ch only provides the Swiss terrain extent. Keep zoom-out close
    // to the normal national overview so the empty surroundings never dominate.
    this.controls.maxDistance = mobile ? 460_000 : 520_000;

    this.raycaster = new THREE.Raycaster();
    this.baseOverlay = null;
    this.optionalOverlays = new Map();
    this.routeObjects = [];
    this.selectionObjects = [];
    this.nameObjects = [];
    this.namesVisible = false;
    this.namesRequest = 0;
    this.lineMaterials = new Set();
    this.setBaseLayer('topo');
    this.setOverlay('hiking', true);
    // Keep the layer registered so the 3D material layout remains stable, but
    // do not lock or download any label tiles until the user selects imagery.
    this.namesOverlay = this.createWmtsOverlay('names', 0, false);
    this.imagePlugin.addOverlay(this.namesOverlay, 30);

    this.resizeObserver = new ResizeObserver(() => this.resize());
    this.resizeObserver.observe(container);
    this.resize();
    // Start like a conventional 2D map. GlobeControls remain unchanged, so
    // users can still tilt and rotate the live 3D terrain afterwards.
    this.focusInitialView();
    this.running = true;
    this.animate();
  }

  createWmtsOverlay(name, opacity = 1, enabled = true) {
    const layer = LAYERS[name];
    return new ToggleableWmtsOverlay({
      url: wmtsTemplate(layer),
      layer: layer.id,
      tileMatrixSet: '3857',
      projection: 'EPSG:3857',
      format: layer.format,
      levels: 20,
      opacity,
      contentBoundingBox: [
        radians(SWISS_BOUNDS.west),
        radians(SWISS_BOUNDS.south),
        radians(SWISS_BOUNDS.east),
        radians(SWISS_BOUNDS.north),
      ],
    }, enabled);
  }

  setBaseLayer(name) {
    if (this.baseOverlay) this.imagePlugin.deleteOverlay(this.baseOverlay);
    this.baseOverlay = this.createWmtsOverlay(name, 1);
    this.imagePlugin.addOverlay(this.baseOverlay, -10);
  }

  setOverlay(name, visible) {
    const existing = this.optionalOverlays.get(name);
    if (existing && !visible) {
      this.imagePlugin.deleteOverlay(existing);
      this.optionalOverlays.delete(name);
      return;
    }
    if (!existing && visible) {
      const opacity = name === 'hiking' ? 0.9 : 0.95;
      const order = name === 'hiking' ? 10 : 20;
      const overlay = this.createWmtsOverlay(name, opacity);
      this.optionalOverlays.set(name, overlay);
      this.imagePlugin.addOverlay(overlay, order);
    }
  }

  setNamesVisible(visible) {
    this.namesVisible = visible;
    this.nameObjects.forEach((object) => (object.visible = visible));
    this.namesOverlay.enabled = visible;
    this.namesOverlay.opacity = visible ? 1 : 0;
    if (visible) this.imagePlugin.activateOverlay(this.namesOverlay);
  }

  localPosition([lon, lat, height = 0], target = new THREE.Vector3(), surfaceOffset = 35) {
    return this.tiles.ellipsoid.getCartographicToPosition(
      radians(lat),
      radians(lon),
      Math.max(0, height) + surfaceOffset,
      target,
    );
  }

  worldPosition(coordinate, target = new THREE.Vector3(), surfaceOffset = 35) {
    this.tiles.group.updateMatrixWorld(true);
    return this.localPosition(coordinate, target, surfaceOffset).applyMatrix4(this.tiles.group.matrixWorld);
  }

  focusSwitzerland(topDown = false) {
    this.tiles.errorTarget = this.defaultTerrainErrorTarget;
    const altitude = topDown ? (this.mobile ? 550_000 : 330_000) : 410_000;
    this.focusCoordinate([8.23, 46.83], altitude, topDown);
  }

  focusInitialView() {
    this.tiles.errorTarget = this.mobile ? 1 : this.defaultTerrainErrorTarget;
    if (this.mobile) {
      // A full national overview is too wide for a portrait screen and exposes
      // the white map area north of Switzerland. Start closer and slightly
      // farther south so the visible mobile map is fully covered.
      this.focusCoordinate([8.23, 46.25], 280_000, true);
      return;
    }
    this.focusSwitzerland(true);
  }

  focusCoordinate([lon, lat], altitude = 180_000, topDown = false) {
    this.tiles.group.updateMatrixWorld(true);
    const localSurface = this.localPosition([lon, lat, 0], new THREE.Vector3());
    const surface = localSurface.clone().applyMatrix4(this.tiles.group.matrixWorld);
    const normalLocal = this.tiles.ellipsoid
      .getCartographicToNormal(radians(lat), radians(lon), new THREE.Vector3())
      .normalize();
    const normal = normalLocal.clone().transformDirection(this.tiles.group.matrixWorld).normalize();
    const enu = this.tiles.ellipsoid.getEastNorthUpFrame(
      radians(lat),
      radians(lon),
      0,
      new THREE.Matrix4(),
    );
    const north = new THREE.Vector3().setFromMatrixColumn(enu, 1);
    north.transformDirection(this.tiles.group.matrixWorld).normalize();
    this.camera.position.copy(surface).addScaledVector(normal, altitude);
    if (!topDown) this.camera.position.addScaledVector(north, -altitude * 0.55);
    this.camera.up.copy(north);
    this.camera.lookAt(surface);
    this.camera.updateMatrixWorld();
    this.controls.resetState?.();
  }

  focusRoute(coordinates) {
    if (!coordinates?.length) return;
    // Refine immediately after jumping to a route. A coarse error target keeps
    // low-zoom terrain parents visible and stretches their map imagery.
    this.tiles.errorTarget = this.routeTerrainErrorTarget;
    let minLon = Infinity;
    let minLat = Infinity;
    let maxLon = -Infinity;
    let maxLat = -Infinity;
    for (const coordinate of coordinates) {
      minLon = Math.min(minLon, coordinate[0]);
      minLat = Math.min(minLat, coordinate[1]);
      maxLon = Math.max(maxLon, coordinate[0]);
      maxLat = Math.max(maxLat, coordinate[1]);
    }
    const lon = (minLon + maxLon) / 2;
    const lat = (minLat + maxLat) / 2;
    const northSouthMeters = (maxLat - minLat) * 111_320;
    const eastWestMeters =
      (maxLon - minLon) * 111_320 * Math.max(0.2, Math.cos(radians(lat)));
    const routeExtentMeters = Math.hypot(eastWestMeters, northSouthMeters);
    // Keep the complete route in view while moving substantially closer than
    // the regional overview used before generation.
    const altitude = Math.max(5_500, Math.min(45_000, routeExtentMeters * 1.25 + 2_500));
    // Present every generated route like a conventional 2D map first. The
    // unchanged GlobeControls still let users tilt into the 3D terrain.
    this.focusCoordinate([lon, lat], altitude, true);
  }

  pickCoordinate(clientX, clientY) {
    const rect = this.renderer.domElement.getBoundingClientRect();
    const pointer = new THREE.Vector2(
      ((clientX - rect.left) / rect.width) * 2 - 1,
      -((clientY - rect.top) / rect.height) * 2 + 1,
    );
    this.raycaster.setFromCamera(pointer, this.camera);
    const inverse = this.tiles.group.matrixWorld.clone().invert();
    const ray = this.raycaster.ray.clone().applyMatrix4(inverse);
    const point = this.tiles.ellipsoid.intersectRay(ray, new THREE.Vector3());
    if (!point) return null;
    this.tiles.ellipsoid.getPositionToCartographic(point, CARTOGRAPHIC);
    return [(CARTOGRAPHIC.lon * 180) / Math.PI, (CARTOGRAPHIC.lat * 180) / Math.PI];
  }

  clearObjects(collection) {
    for (const object of collection) {
      object.removeFromParent();
      object.traverse((child) => {
        child.element?.remove();
        child.geometry?.dispose();
        const materials = Array.isArray(child.material) ? child.material : [child.material];
        for (const material of materials) {
          if (!material) continue;
          this.lineMaterials.delete(material);
          material.dispose();
        }
      });
    }
    collection.length = 0;
  }

  makeLine(
    coordinates,
    color,
    width = 3,
    dashed = false,
    opacity = 0.98,
    surfaceOffset = 35,
    depthTest = false,
  ) {
    const positions = [];
    for (const coordinate of coordinates) {
      const position = this.worldPosition(coordinate, new THREE.Vector3(), surfaceOffset);
      positions.push(position.x, position.y, position.z);
    }
    const geometry = new LineGeometry();
    geometry.setPositions(positions);
    const material = new LineMaterial({
      color,
      linewidth: width,
      worldUnits: false,
      dashed,
      dashScale: 1,
      dashSize: 2,
      gapSize: 1.5,
      transparent: true,
      opacity,
      depthTest,
      depthWrite: false,
      toneMapped: false,
    });
    material.resolution.set(this.container.clientWidth, this.container.clientHeight);
    this.lineMaterials.add(material);
    const line = new Line2(geometry, material);
    if (dashed) line.computeLineDistances();
    line.renderOrder = 100;
    line.frustumCulled = false;
    return line;
  }

  makeAreaFill(coordinates, color = 0x155c9c, opacity = 0.38) {
    const polygon = coordinates.map((coordinate) => [...coordinate]);
    if (
      polygon.length > 2 &&
      polygon[0][0] === polygon.at(-1)[0] &&
      polygon[0][1] === polygon.at(-1)[1]
    ) {
      polygon.pop();
    }
    if (polygon.length < 3) return null;

    const triangles = THREE.ShapeUtils.triangulateShape(
      polygon.map((coordinate) => new THREE.Vector2(coordinate[0], coordinate[1])),
      [],
    );
    const positions = [];
    for (const coordinate of polygon) {
      const position = this.worldPosition([coordinate[0], coordinate[1], coordinate[2] || 100]);
      positions.push(position.x, position.y, position.z);
    }
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geometry.setIndex(triangles.flat());
    const material = new THREE.MeshBasicMaterial({
      color,
      transparent: true,
      opacity,
      side: THREE.DoubleSide,
      depthTest: false,
      depthWrite: false,
      toneMapped: false,
    });
    const fill = new THREE.Mesh(geometry, material);
    fill.renderOrder = 90;
    fill.frustumCulled = false;
    return fill;
  }

  addMarker(coordinate, color, scale = 340, opacity = 1) {
    const group = new THREE.Group();
    const markerMaterial = new THREE.MeshBasicMaterial({
      color,
      transparent: opacity < 1,
      opacity,
      depthTest: false,
      depthWrite: false,
      toneMapped: false,
    });
    const stem = new THREE.Mesh(
      new THREE.CylinderGeometry(scale * 0.18, scale * 0.18, scale * 1.3, 12),
      markerMaterial,
    );
    stem.rotation.x = Math.PI / 2;
    const head = new THREE.Mesh(
      new THREE.SphereGeometry(scale * 0.42, 20, 12),
      markerMaterial.clone(),
    );
    head.position.z = scale * 0.85;
    group.add(stem, head);
    stem.renderOrder = 230;
    head.renderOrder = 230;
    stem.frustumCulled = false;
    head.frustumCulled = false;
    group.position.copy(this.worldPosition(coordinate));
    const normal = this.tiles.ellipsoid
      .getCartographicToNormal(radians(coordinate[1]), radians(coordinate[0]), new THREE.Vector3())
      .normalize()
      .transformDirection(this.tiles.group.matrixWorld);
    group.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), normal);
    group.renderOrder = 110;
    this.overlayGroup.add(group);
    return group;
  }

  addRoutePin(coordinate, stopName, type) {
    const element = document.createElement('div');
    element.className = `route-map-pin route-map-pin--${type}`;

    const pin = document.createElement('span');
    pin.className = 'route-map-pin__shape';
    const center = document.createElement('span');
    center.className = 'route-map-pin__center';
    center.textContent = type === 'loop' ? '↺' : type === 'start' ? 'S' : 'Z';
    pin.append(center);

    const caption = document.createElement('span');
    caption.className = 'route-map-pin__caption';
    const role = type === 'loop' ? 'Start/Ziel' : type === 'start' ? 'Start' : 'Ziel';
    caption.textContent = `${role} · ${stopName}`;
    element.append(pin, caption);

    const object = new CSS2DObject(element);
    // The marker centre is the exact first/last route coordinate. This avoids
    // the apparent offset of a teardrop whose body hangs above its anchor.
    object.center.set(0.5, 0.5);
    object.position.copy(
      this.worldPosition(coordinate, new THREE.Vector3(), ROUTE_SURFACE_OFFSET_METERS),
    );
    this.overlayGroup.add(object);
    return object;
  }

  addTextLabel(coordinate, text, className) {
    const element = document.createElement('div');
    element.className = className;
    element.textContent = text;
    const object = new CSS2DObject(element);
    object.center.set(0.5, 0.5);
    object.position.copy(this.worldPosition(coordinate));
    object.visible = this.namesVisible;
    this.overlayGroup.add(object);
    this.nameObjects.push(object);
    return object;
  }

  routeHeightNear(coordinate, routeCoordinates) {
    let closest = routeCoordinates[0];
    let closestDistance = Infinity;
    for (const routeCoordinate of routeCoordinates) {
      const dx = routeCoordinate[0] - coordinate[0];
      const dy = routeCoordinate[1] - coordinate[1];
      const distance = dx * dx + dy * dy;
      if (distance < closestDistance) {
        closestDistance = distance;
        closest = routeCoordinate;
      }
    }
    return closest?.[2] || 0;
  }

  labelName(html, fallback) {
    const holder = document.createElement('span');
    holder.innerHTML = html || '';
    return holder.querySelector('b')?.textContent?.trim() || holder.textContent?.trim() || fallback;
  }

  async showContextLabels(routeCoordinates, nearbyStops = []) {
    this.clearObjects(this.nameObjects);
    for (const stop of nearbyStops || []) {
      this.addTextLabel(
        [stop.lon, stop.lat, stop.elevation],
        stop.name,
        'nearby-stop-label',
      );
    }

    if (!routeCoordinates.length) return;
    const request = ++this.namesRequest;
    let minLon = Infinity;
    let minLat = Infinity;
    let maxLon = -Infinity;
    let maxLat = -Infinity;
    for (const coordinate of routeCoordinates) {
      minLon = Math.min(minLon, coordinate[0]);
      minLat = Math.min(minLat, coordinate[1]);
      maxLon = Math.max(maxLon, coordinate[0]);
      maxLat = Math.max(maxLat, coordinate[1]);
    }
    const lonMargin = Math.max(0.025, (maxLon - minLon) * 0.2);
    const latMargin = Math.max(0.018, (maxLat - minLat) * 0.2);
    const southWest = wgs84ToLv95([minLon - lonMargin, minLat - latMargin]);
    const northEast = wgs84ToLv95([maxLon + lonMargin, maxLat + latMargin]);
    const bounds = [southWest[0], southWest[1], northEast[0], northEast[1]];
    const middleX = (bounds[0] + bounds[2]) / 2;
    const middleY = (bounds[1] + bounds[3]) / 2;
    const areas = [
      [bounds[0], bounds[1], middleX, middleY],
      [middleX, bounds[1], bounds[2], middleY],
      [bounds[0], middleY, middleX, bounds[3]],
      [middleX, middleY, bounds[2], bounds[3]],
    ];
    try {
      const pages = await Promise.all(
        areas.map(async (area) => {
          const parameters = new URLSearchParams({
            bbox: area.join(','),
            type: 'locations',
            origins: 'gg25,gazetteer',
            limit: '50',
            sr: '2056',
          });
          const response = await fetch(`${GEOADMIN.search}?${parameters}`);
          if (!response.ok) throw new Error(`Ortsnamen ${response.status}`);
          return (await response.json()).results || [];
        }),
      );
      if (request !== this.namesRequest) return;
      const seen = new Set();
      const places = pages
        .flat()
        .filter(
          (result) =>
            result.attrs?.origin === 'gg25' ||
            result.attrs?.objectclass === 'TLM_SIEDLUNGSNAME',
        )
        .map((result) => ({
          name: this.labelName(result.attrs?.label, result.attrs?.detail),
          lon: Number(result.attrs?.lon),
          lat: Number(result.attrs?.lat),
          rank: Number(result.attrs?.rank || 9),
        }))
        .filter((place) => {
          const key = place.name.toLocaleLowerCase('de-CH');
          if (!place.name || !Number.isFinite(place.lon) || !Number.isFinite(place.lat) || seen.has(key)) {
            return false;
          }
          seen.add(key);
          return true;
        })
        .sort((a, b) => a.rank - b.rank)
        .slice(0, 14);
      for (const place of places) {
        const elevation = this.routeHeightNear([place.lon, place.lat], routeCoordinates);
        this.addTextLabel(
          [place.lon, place.lat, elevation],
          place.name,
          place.rank <= 5 ? 'place-map-label place-map-label--major' : 'place-map-label',
        );
      }
    } catch {
      // The map remains useful when the optional live labels are unavailable.
    }
  }

  showRoute(feature, startStop, endStop, nearbyStops = []) {
    this.clearObjects(this.routeObjects);
    this.clearSelection();
    const coordinates = feature.geometry.coordinates;
    const routeHalo = this.makeLine(
      coordinates,
      0xffffff,
      9,
      false,
      0.98,
      ROUTE_SURFACE_OFFSET_METERS,
      true,
    );
    routeHalo.renderOrder = 210;
    const route = this.makeLine(
      coordinates,
      0xff5d3d,
      5.5,
      false,
      0.98,
      ROUTE_SURFACE_OFFSET_METERS,
      true,
    );
    route.renderOrder = 220;
    this.overlayGroup.add(routeHalo, route);
    this.routeObjects.push(routeHalo, route);
    if (coordinates.length) {
      const isLoop = endStop.id === startStop.id;
      const start = this.addRoutePin(
        coordinates[0],
        startStop.name,
        isLoop ? 'loop' : 'start',
      );
      this.routeObjects.push(start);
      if (!isLoop) {
        const end = this.addRoutePin(coordinates.at(-1), endStop.name, 'end');
        this.routeObjects.push(end);
      }
    }
    void this.showContextLabels(coordinates, nearbyStops);
    this.focusRoute(coordinates);
  }

  clearRoute() {
    this.namesRequest += 1;
    this.clearObjects(this.routeObjects);
    this.clearObjects(this.nameObjects);
  }

  showPointSelection(coordinate, radiusKm) {
    this.clearObjects(this.selectionObjects);
    const ring = [];
    for (let index = 0; index <= 96; index += 1) {
      const angle = (index / 96) * Math.PI * 2;
      const latOffset = (Math.sin(angle) * radiusKm) / 111.2;
      const lonOffset = (Math.cos(angle) * radiusKm) / (111.2 * Math.cos(radians(coordinate[1])));
      ring.push([coordinate[0] + lonOffset, coordinate[1] + latOffset, 100]);
    }
    const fill = this.makeAreaFill(ring);
    if (fill) {
      this.overlayGroup.add(fill);
      this.selectionObjects.push(fill);
    }
    const line = this.makeLine(ring, 0x155c9c, 3, true, 0.72);
    this.overlayGroup.add(line);
    this.selectionObjects.push(line);
    const marker = this.addMarker([coordinate[0], coordinate[1], 0], 0x155c9c, 220, 0.72);
    this.selectionObjects.push(marker);
  }

  addSelectionPointLabel(coordinate, index) {
    const element = document.createElement('div');
    element.className = `selection-point-label${index === 0 ? ' selection-point-label--start' : ''}`;
    element.textContent = String(index + 1);
    const object = new CSS2DObject(element);
    object.center.set(0.5, 0.5);
    object.position.copy(this.worldPosition([coordinate[0], coordinate[1], 0], new THREE.Vector3(), 260));
    this.overlayGroup.add(object);
    return object;
  }

  showPolygonSelection(coordinates, closed = false) {
    this.clearObjects(this.selectionObjects);
    if (!coordinates.length) return;
    const lineCoordinates = coordinates.map((coordinate) => [...coordinate, 100]);
    if (closed && coordinates.length >= 3) lineCoordinates.push([...coordinates[0], 100]);
    if (closed && coordinates.length >= 3) {
      const fill = this.makeAreaFill(lineCoordinates);
      if (fill) {
        this.overlayGroup.add(fill);
        this.selectionObjects.push(fill);
      }
    }
    if (lineCoordinates.length >= 2) {
      const line = this.makeLine(lineCoordinates, 0x155c9c, 4.5, !closed, 0.96);
      this.overlayGroup.add(line);
      this.selectionObjects.push(line);
    }
    for (let index = 0; index < coordinates.length; index += 1) {
      const coordinate = coordinates[index];
      const marker = this.addMarker(
        [coordinate[0], coordinate[1], 0],
        index === 0 ? 0x2fb978 : 0x155c9c,
        index === 0 ? 220 : 175,
        1,
      );
      const label = this.addSelectionPointLabel(coordinate, index);
      this.selectionObjects.push(marker, label);
    }
  }

  clearSelection() {
    this.clearObjects(this.selectionObjects);
  }

  resize() {
    const width = Math.max(1, this.container.clientWidth);
    const height = Math.max(1, this.container.clientHeight);
    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();
    this.renderer.setSize(width, height, false);
    this.labelRenderer.setSize(width, height);
    this.tiles.setResolutionFromRenderer(this.camera, this.renderer);
    this.lineMaterials.forEach((material) => material.resolution.set(width, height));
  }

  animate = () => {
    if (!this.running) return;
    requestAnimationFrame(this.animate);
    this.controls.update();
    this.camera.updateMatrixWorld();
    this.tiles.setCamera(this.camera);
    this.tiles.update();
    this.renderer.render(this.scene, this.camera);
    this.labelRenderer.render(this.scene, this.camera);
  };

  dispose() {
    this.running = false;
    this.resizeObserver.disconnect();
    this.controls.dispose();
    this.tiles.dispose();
    this.renderer.dispose();
    this.labelRenderer.domElement.remove();
  }
}
