function escapeXml(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&apos;');
}

export function createGpx(route, geoJson) {
  const title =
    route.routeType === 'loop'
      ? `Rundwanderung ab ${route.startStop.name}`
      : `${route.startStop.name} – ${route.endStop.name}`;
  const trackPoints = geoJson.geometry.coordinates
    .map(
      ([lon, lat, elevation]) =>
        `      <trkpt lat="${lat.toFixed(7)}" lon="${lon.toFixed(7)}"><ele>${Number(elevation || 0).toFixed(1)}</ele></trkpt>`,
    )
    .join('\n');
  return `<?xml version="1.0" encoding="UTF-8"?>
<gpx version="1.1" creator="RandomHike Schweiz" xmlns="http://www.topografix.com/GPX/1/1" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xsi:schemaLocation="http://www.topografix.com/GPX/1/1 http://www.topografix.com/GPX/1/1/gpx.xsd">
  <metadata>
    <name>${escapeXml(title)}</name>
    <desc>Automatisch erzeugte Wanderroute. Daten: geo.admin.ch, Stand ${escapeXml(route.dataVersion)}. Lokale Signalisation und Verhältnisse prüfen.</desc>
    <time>${new Date().toISOString()}</time>
  </metadata>
  <wpt lat="${route.startStop.lat}" lon="${route.startStop.lon}"><name>${escapeXml(route.startStop.name)}</name><type>Start</type></wpt>
  <wpt lat="${route.endStop.lat}" lon="${route.endStop.lon}"><name>${escapeXml(route.endStop.name)}</name><type>Ziel</type></wpt>
  <trk>
    <name>${escapeXml(title)}</name>
    <type>Wandern</type>
    <trkseg>
${trackPoints}
    </trkseg>
  </trk>
</gpx>`;
}

export function downloadGpx(route, geoJson) {
  const blob = new Blob([createGpx(route, geoJson)], { type: 'application/gpx+xml;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = `randomhike-${route.seed.replace(/[^a-z0-9-]/gi, '-').slice(0, 28)}.gpx`;
  anchor.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
