import { GEOADMIN } from './constants.js';
import { bboxOfCoordinates, lv95ToWgs84 } from './geo.js';

const CLOSURE_CACHE_KEY = 'randomhike-closures-v1';
const CLOSURE_TTL = 6 * 60 * 60 * 1000;

function cachedClosures() {
  try {
    const cached = JSON.parse(localStorage.getItem(CLOSURE_CACHE_KEY));
    if (cached && Date.now() - cached.timestamp < CLOSURE_TTL) return cached;
  } catch {
    // A blocked localStorage must never prevent route generation.
  }
  return null;
}

function saveClosures(value) {
  try {
    localStorage.setItem(CLOSURE_CACHE_KEY, JSON.stringify(value));
  } catch {
    // Cache is an optimization only.
  }
}

export async function loadClosures() {
  const cached = cachedClosures();
  if (cached) return cached;
  const results = [];
  const limit = 200;
  let offset = 0;
  while (true) {
    const parameters = new URLSearchParams({
      geometry: '2480000,1070000,2840000,1300000',
      geometryType: 'esriGeometryEnvelope',
      layers: `all:${GEOADMIN.closuresLayer}`,
      tolerance: '0',
      returnGeometry: 'true',
      geometryFormat: 'geojson',
      sr: '2056',
      lang: 'de',
      limit: String(limit),
      offset: String(offset),
    });
    const response = await fetch(`${GEOADMIN.identify}?${parameters}`);
    if (!response.ok) throw new Error('Aktuelle Sperrungen sind momentan nicht erreichbar.');
    const page = await response.json();
    results.push(...(page.results || []));
    if ((page.results || []).length < limit) break;
    offset += limit;
  }
  const closures = results
    .filter((feature) => feature.geometry?.coordinates)
    .map((feature) => {
      const coordinates =
        feature.geometry.type === 'MultiLineString'
          ? feature.geometry.coordinates.flat()
          : feature.geometry.coordinates;
      return {
        id: feature.id,
        bbox: feature.bbox || bboxOfCoordinates(coordinates),
        coordinates,
        reason: feature.properties?.reason_de || feature.properties?.abstract_de || 'Wegsperrung',
      };
    });
  const value = { timestamp: Date.now(), closures };
  saveClosures(value);
  return value;
}

export function routeGraphProfile(route) {
  const points = [];
  let distance = 0;
  const coordinates = route.coordinatesLv95;
  for (let index = 0; index < coordinates.length; index += 3) {
    if (index) {
      distance += Math.hypot(
        coordinates[index] - coordinates[index - 3],
        coordinates[index + 1] - coordinates[index - 2],
      );
    }
    points.push({
      distance,
      elevation: coordinates[index + 2],
      coordinate: lv95ToWgs84([coordinates[index], coordinates[index + 1]]),
    });
  }
  return { points, source: 'Weggraph' };
}

function fallbackProfile(route) {
  return {
    ...routeGraphProfile(route),
    warning: 'Höhenprofil-API nicht erreichbar; Graphhöhen werden angezeigt.',
  };
}

export async function loadElevationProfile(route) {
  const line = [];
  for (let index = 0; index < route.coordinatesLv95.length; index += 3) {
    line.push([route.coordinatesLv95[index], route.coordinatesLv95[index + 1]]);
  }
  const body = new URLSearchParams({
    geom: JSON.stringify({ type: 'LineString', coordinates: line }),
    sr: '2056',
    nb_points: String(Math.min(400, Math.max(120, line.length * 3))),
    offset: '2',
    distinct_points: 'false',
  });
  try {
    const response = await fetch(GEOADMIN.profile, {
      method: 'POST',
      // The profile service validates this media type strictly and rejects the
      // otherwise harmless charset parameter with HTTP 415.
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body,
    });
    if (!response.ok) throw new Error(`Profil ${response.status}`);
    const values = await response.json();
    const points = values.map((value) => ({
      distance: Number(value.dist),
      elevation: Number(value.alts?.COMB ?? value.alts?.DTM2 ?? 0),
      coordinate: lv95ToWgs84([Number(value.easting), Number(value.northing)]),
    }));
    return { points, source: 'geo.admin.ch' };
  } catch {
    return fallbackProfile(route);
  }
}

export function routeGeoJson(route, profile) {
  const profileCoordinates = profile?.points?.map((point) => [
    point.coordinate[0],
    point.coordinate[1],
    point.elevation,
  ]);
  const routeCoordinates = [];
  for (let index = 0; index < route.coordinatesLv95.length; index += 3) {
    const [lon, lat] = lv95ToWgs84([
      route.coordinatesLv95[index],
      route.coordinatesLv95[index + 1],
    ]);
    routeCoordinates.push([lon, lat, route.coordinatesLv95[index + 2]]);
  }
  return {
    type: 'Feature',
    properties: {
      routeType: route.routeType,
      seed: route.seed,
      dataVersion: route.dataVersion,
    },
    geometry: {
      type: 'LineString',
      coordinates: profileCoordinates?.length > 1 ? profileCoordinates : routeCoordinates,
    },
  };
}
